// Protected spans: byte-exact substrings of the system prompt that every
// challenger must still contain exactly once (seeds/protected-spans.json,
// generated by tools/make_spans.py from the v0 champions). The list is the
// product contract, not the whole prompt: the optimizer may rewrite anything
// else, including section 3's wording around the quotation rule.

export interface Span { id: string; text: string; sha256?: string }

export interface SpanCheck { ok: boolean; missing: string[]; duplicated: string[] }

export function checkSpans(systemPrompt: string, spans: Span[]): SpanCheck {
  const missing: string[] = [], duplicated: string[] = [];
  for (const s of spans) {
    const first = systemPrompt.indexOf(s.text);
    if (first < 0) { missing.push(s.id); continue; }
    if (systemPrompt.indexOf(s.text, first + 1) >= 0) duplicated.push(s.id);
  }
  return { ok: missing.length === 0 && duplicated.length === 0, missing, duplicated };
}

/** Words that would contradict a protected span even though the span itself is intact. */
const CONTRADICTIONS: { span: string; pattern: RegExp; what: string }[] = [
  { span: "fictional_cast", pattern: /\b(?:impersonate|speak as|in the voice of) (?:the )?(?:real|actual|historical) (?:thinker|author|person)s?\b/i, what: "asks the minds to impersonate real people" },
  { span: "quotation_rule", pattern: /\bquote[s]? (?:freely|any|all) (?:book|passage|source)s?\b/i, what: "loosens the quotation rule" },
  { span: "turn_range", pattern: /\b(?:at least|exactly|no more than) (?:1[3-9]|[2-9]\d) (?:speaking )?turns\b/i, what: "changes the turn count" },
  { span: "ending", pattern: /\bend (?:the synthesis |section E )?with a question\b/i, what: "asks for an ending question" },
];

/**
 * With `base` (the champion), a pattern is reported only when the candidate has MORE matches than the champion:
 * the original prompt's own negated rules ("Do not … impersonate real thinkers", "Do not end with a question")
 * match these patterns, so scanning the whole candidate would reject every proposal. Removing or rewording the
 * negation itself breaks a protected span, which checkSpans reports.
 */
export function contradictionProblems(systemPrompt: string, base?: string): string[] {
  const count = (re: RegExp, s: string) => (s.match(new RegExp(re.source, "gi")) ?? []).length;
  return CONTRADICTIONS
    .filter((c) => (base === undefined ? c.pattern.test(systemPrompt) : count(c.pattern, systemPrompt) > count(c.pattern, base)))
    .map((c) => `${c.span}: new text ${c.what}`);
}
